#!/usr/bin/env python3
"""Build the self-contained Persian user guide and its printable PDF.

Run from any directory: python docs/user-manual/build_manual.py --pdf
Requires Playwright and a Chromium executable only for PDF generation.
The app is not started and application data is never read by this builder.
"""
from __future__ import annotations

import argparse
import base64
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
OUTPUT = ROOT / "deliverables"
SCREENSHOTS = HERE / "assets" / "screens"
FONT_ROOT = ROOT / "src" / "main" / "resources" / "static" / "fonts"


def figure(filename: str, caption: str, size: str = "") -> str:
    path = SCREENSHOTS / filename
    encoded = base64.b64encode(path.read_bytes()).decode("ascii")
    return f'<figure class="screen {size}"><img loading="eager" src="data:image/png;base64,{encoded}" alt="{caption}"><figcaption>{caption} <span>تصویر با دادهٔ نمونه</span></figcaption></figure>'


def callout(title: str, text: str, kind: str = "info") -> str:
    return f'<aside class="callout {kind}"><strong>{title}</strong><p>{text}</p></aside>'


def card(title: str, text: str, style: str = "") -> str:
    return f'<div class="card {style}"><h3 class="card-title">{title}</h3>{text}</div>'


def steps(items: list[tuple[str, str]]) -> str:
    return '<ol class="steps">' + ''.join(f'<li><span class="step-number">{i}</span><div><strong>{title}</strong><p>{text}</p></div></li>' for i, (title, text) in enumerate(items, 1)) + '</ol>'


def table(headers: list[str], rows: list[list[str]], style: str = "") -> str:
    return '<div class="table-wrap"><table class="data-table ' + style + '"><thead><tr>' + ''.join(f'<th>{x}</th>' for x in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join(f'<td>{x}</td>' for x in row) + '</tr>' for row in rows) + '</tbody></table></div>'


