def build_html() -> Path:
    all_pages = pages()
    css = (HERE / "manual.css").read_text(encoding="utf-8")
    js = (HERE / "manual.js").read_text(encoding="utf-8")
    font_css = ''
    for weight, name in [(400, "Regular"), (700, "Bold")]:
        font = base64.b64encode((FONT_ROOT / f"Vazirmatn-FD-{name}.woff2").read_bytes()).decode("ascii")
        font_css += f'@font-face{{font-family:"Vazirmatn FD";font-style:normal;font-weight:{weight};font-display:block;src:url(data:font/woff2;base64,{font}) format("woff2")}}'
    navigation = ''.join(f'<a href="#{p["anchor"]}"><span>{p["title"]}</span><small>{i}</small></a>' for i, p in enumerate(all_pages, 1))
    sheets = ''
    for i, p in enumerate(all_pages, 1):
        if p['anchor'] == 'cover':
            sheets += f'<section class="sheet cover" id="cover" data-title="{p["title"]}">{p["body"]}</section>'
            continue
        sheets += f'''<section class="sheet" id="{p['anchor']}" data-title="{p['title']}">
          <header class="page-header"><span class="mini-brand">پیگیر <b>PEYGIR</b></span><span>{p['chapter']}</span></header>
          <div class="page-kicker"><span class="page-number">{i:02d}</span><span class="audience">{p['audience']}</span></div>
          <h1 class="page-title">{p['title']}</h1><p class="lede">{p['lead']}</p>
          <div class="page-body">{p['body']}</div>
          <footer class="page-footer"><span>راهنمای کاربری پیگیر <span class="footer-dot">•</span> نسخه نخست</span><span>صفحهٔ {i:02d} از {len(all_pages):02d}</span></footer>
        </section>'''
    doc = f'''<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="راهنمای فارسی پیگیر برای ثبت گزارش، تأیید، آمار و مدیریت کاربران و تیم‌ها"><title>راهنمای کاربری پیگیر</title><style>{font_css}\n{css}</style></head><body>
      <div class="manual-shell">
        <aside class="guide-sidebar" aria-label="فهرست راهنما"><a class="sidebar-brand" href="#cover"><span class="brand-mark">پ</span><span>راهنمای پیگیر<small>PEYGIR USER GUIDE</small></span></a>
          <label class="guide-search"><span>جستجو در راهنما</span><input id="guideSearch" type="search" placeholder="مثلاً رمز، تیم یا Excel" autocomplete="off" aria-label="جستجو در متن راهنما"></label>
          <p id="searchCount" class="small muted" role="status" aria-live="polite">۱۹ صفحهٔ راهنما</p>
          <nav class="guide-nav">{navigation}</nav><p class="sidebar-note">نسخه نخست • ۱۴ مهر ۱۴۰۵<br>تمام تصاویر، دادهٔ نمونه دارند.</p>
        </aside>
        <main class="sheets"><div class="toolbar"><span>راهنمای کاربری پیگیر</span><div><button id="menuToggle" type="button" aria-controls="guideMenu" aria-expanded="false">فهرست</button><button class="print-button" id="printGuide" type="button">چاپ / ذخیره PDF</button></div></div>
          <div class="progress-track" aria-hidden="true"><div class="progress-fill" id="readingProgress"></div></div>
          <div class="no-results" id="noResults" hidden>صفحه‌ای با این عبارت پیدا نشد. عبارت کوتاه‌تری بنویسید.</div>
          {sheets}
        </main>
      </div><dialog id="imageZoom"><button type="button" id="closeZoom" aria-label="بستن تصویر">بستن</button><img alt="تصویر بزرگ‌شده صفحهٔ برنامه"></dialog><script>{js}</script>
    </body></html>'''
    doc = doc.replace('<aside class="guide-sidebar"', '<aside id="guideMenu" class="guide-sidebar"')
    license_text = '\n'.join(line.rstrip() for line in (FONT_ROOT / 'OFL-Vazirmatn.txt').read_text(encoding='utf-8').splitlines()).replace('--', '- -')
    doc = doc.replace('</head>', '<!-- Embedded Vazirmatn font license\n' + license_text + '\n--></head>')
    OUTPUT.mkdir(exist_ok=True)
    out = OUTPUT / "peygir-user-manual.html"
    out.write_text(doc, encoding="utf-8")
    return out


def build_pdf(html: Path, chromium: str) -> None:
    from playwright.sync_api import sync_playwright
    with sync_playwright() as pw:
        browser = pw.chromium.launch(executable_path=chromium, args=["--no-sandbox"])
        page = browser.new_page(viewport={"width": 1440, "height": 1100})
        page.set_content(html.read_text(encoding="utf-8"), wait_until="load")
        page.evaluate("document.fonts.ready")
        page.emulate_media(media="print")
        page.evaluate("Promise.all(Array.from(document.images).map(img => img.decode().catch(() => null)))")
        overflow = page.evaluate("""() => Array.from(document.querySelectorAll('.sheet')).flatMap(s => {
          const body = s.querySelector('.page-body'); const footer = s.querySelector('.page-footer');
          if (!body || !footer) return [];
          return body.getBoundingClientRect().bottom > footer.getBoundingClientRect().top - 8 ? [{id:s.id,bodyBottom:body.getBoundingClientRect().bottom,footerTop:footer.getBoundingClientRect().top}] : [];
        })""")
        if overflow:
            browser.close()
            raise RuntimeError(f"Page content overlaps footer: {overflow}")
        page.pdf(path=str(OUTPUT / "peygir-user-manual.pdf"), format="A4", prefer_css_page_size=True, print_background=True, display_header_footer=False, margin=dict(top="0", right="0", bottom="0", left="0"))
        browser.close()


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--pdf", action="store_true")
    parser.add_argument("--chromium", default="/usr/bin/chromium")
    args = parser.parse_args()
    html = build_html()
    print(f"Built {html.relative_to(ROOT)}")
    if args.pdf:
        build_pdf(html, args.chromium)
        print("Built deliverables/peygir-user-manual.pdf")
